files.content:
.slider {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  inline-size: 100%;
}
.slider[data-disabled] {
  opacity: var(--disabled-opacity);
  cursor: not-allowed;
}

.slider-labelrow {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--space-3);
}
.slider-label {
  font-size: var(--font-sm);
  color: var(--foreground);
}
.slider-value {
  font-size: var(--font-sm);
  font-variant-numeric: tabular-nums;
  color: var(--muted-foreground);
}

/* Native range, restyled. The filled portion left of the thumb uses --pct set
 * inline; the rest is the track colour. Thumb and track are vendor-prefixed
 * because the two engines expose different pseudo-elements. */
.slider-input {
  --pct: 0%; /* filled fraction; overridden inline from the value */
  inline-size: 100%;
  block-size: var(--space-6);
  margin: 0;
  appearance: none;
  background: transparent;
  cursor: pointer;
}
.slider-input:focus-visible {
  outline: var(--focus-ring);
  outline-offset: var(--ring-offset);
  border-radius: var(--radius-full);
}

.slider-input::-webkit-slider-runnable-track {
  block-size: var(--space-1);
  border-radius: var(--radius-full);
  background: linear-gradient(to right, var(--primary) var(--pct), var(--input) var(--pct));
}
.slider-input::-moz-range-track {
  block-size: var(--space-1);
  border-radius: var(--radius-full);
  background: var(--input);
}
.slider-input::-moz-range-progress {
  block-size: var(--space-1);
  border-radius: var(--radius-full);
  background: var(--primary);
}

/* 24px, not 16: the thumb is the target, and a 16px one is under SC 2.5.8 with
 * no spacing exception available — it is the only thing on the track. */
.slider-input::-webkit-slider-thumb {
  appearance: none;
  inline-size: var(--space-6);
  block-size: var(--space-6);
  margin-block-start: calc((var(--space-1) - var(--space-6)) / 2);
  border-radius: var(--radius-full);
  background: var(--primary);
  border: 2px solid var(--background);
  box-shadow: var(--shadow-sm);
}

/* The thumb answers the pointer. It is the only part you grab, and it gave no
 * sign it knew you were there — the same silence the whole selection family
 * kept. Vendor-prefixed twice because the two engines expose different
 * pseudo-elements and neither accepts a selector list with the other. */
.slider-input:hover::-webkit-slider-thumb { background: var(--primary-hover); }
.slider-input:active::-webkit-slider-thumb { background: var(--primary-active); }
.slider-input:hover::-moz-range-thumb { background: var(--primary-hover); }
.slider-input:active::-moz-range-thumb { background: var(--primary-active); }

.slider-input::-moz-range-thumb {
  inline-size: var(--space-6);
  block-size: var(--space-6);
  border-radius: var(--radius-full);
  background: var(--primary);
  border: 2px solid var(--background);
  box-shadow: var(--shadow-sm);
}

import './Slider.css'
import { useId, type InputHTMLAttributes } from 'react'
import { cn } from '../lib/cn'

/* Monolithic because there is nothing to split: a value, its bounds, its
 * step, and whether the number is shown and in whose words. */
type Props = Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'value' | 'onChange' | 'min' | 'max' | 'step'> & {
  value: number
  onChange: (value: number) => void
  min?: number
  max?: number
  step?: number
  /** Accessible name. */
  label: string
  /** Show the current value at the inline-end of the label row. */
  showValue?: boolean
  /** Formats the shown value (e.g. `(v) => `${v}%``). Default is the raw number. */
  formatValue?: (value: number) => string
}

/* Single-value range input. Built on the native <input type="range">, so the
 * keyboard contract (arrows, Home/End, Page Up/Down) and screen-reader support
 * come for free; this adds the label row, the value read-out and the themed
 * track. The filled portion is driven by a --pct custom property. 
   *
   * Copy: the label carries the unit; the value is announced as the reader would
   * say it, not as a raw number.
   */
export function Slider({
  value, onChange, min = 0, max = 100, step = 1, label, showValue, formatValue, className, disabled, ...rest
}: Props) {
  const id = useId()
  const pct = max === min ? 0 : ((value - min) / (max - min)) * 100
  const shown = formatValue ? formatValue(value) : String(value)

  return (
    <div className={cn('slider', className)} data-disabled={disabled || undefined}>
      <div className="slider-labelrow">
        <label className="slider-label" htmlFor={id}>{label}</label>
        {showValue && <span className="slider-value" aria-hidden="true">{shown}</span>}
      </div>
      <input
        id={id}
        type="range"
        className="slider-input"
        min={min}
        max={max}
        step={step}
        value={value}
        disabled={disabled}
        /* No `aria-label`: the visible <label> above already names this input,
           and an aria-label OVERRIDES it. Two names for one control are the same
           name only until one of them changes, and the one people hear would be
           the one nobody can see (WCAG 2.5.3, Label in Name). Removed 2026-08-26
           after a mutation test showed deleting it changed nothing. */
        onChange={(e) => onChange(Number(e.target.value))}
        style={{ ['--pct' as string]: `${pct}%` }}
        {...rest}
      />
    </div>
  )
}
